#!/usr/bin/env python3
"""Summarize actual saved validation/coverage receipts without claiming full recovery."""
import json,collections
from inventory import ROOT,REPORT

def read(name):return json.loads((REPORT/name).read_text())
def main():
    inventory=read('inventory.json');coverage=read('coverage-summary.json');v=read('artifact-validation.json');b=read('behavior-validation.json')
    pes=[r for r in inventory if r['format'].startswith('PE')];code=[r for r in coverage if r['candidate_starts']]
    total=sum(r['candidate_starts'] for r in coverage);emitted=sum(r['emitted'] for r in coverage);unwind=sum(r['unwind_records'] for r in coverage);unwind_emitted=sum(r['unwind_starts_emitted'] for r in coverage)
    exports=sum(len(r['exports']) for r in pes);exports_emitted=sum(r['export_names_emitted'] for r in coverage)
    omissions=collections.Counter()
    for r in coverage:
        for name in ['timeouts','deferred','other_gaps']:omissions[name]+=r[name]
    literal=0
    for r in pes:literal+=sum(bool(s['literal_argument']) for s in json.loads((REPORT/'modules'/r['module']/'dynamic-lookup-sites.json').read_text()))
    summary_table=['| Module | Candidate starts | Pseudocode | Unwind starts emitted / total | Export names emitted / total |','|---|---:|---:|---:|---:|']
    by={r['module']:r for r in pes}
    for r in coverage:summary_table.append(f"| {r['module']} | {r['candidate_starts']} | {r['emitted']} | {r['unwind_starts_emitted']} / {r['unwind_records']} | {r['export_names_emitted']} / {len(by[r['module']]['exports'])} |")
    validation=['# Validation results','', '## Input preservation and structural consistency','',f"**{v['result'].upper()}**: {v['check_count']} recorded checks, {len(v['failed'])} failed. `artifact-validation.json` is the machine-readable receipt.",'','- Every original file is SHA-256-identical to baseline and byte-identical to its Git HEAD object (see individual receipts).','- REA and pefile hashes, PE architecture/section counts/managed classification cross-checked; GNU objdump architecture independently compared.','- PE checksums recomputed; resource offset/size/hash bounds and PNG chunk CRCs checked. This is not Authenticode validation.','- Internal imported names/ordinals checked against the corresponding supplied export table. Import presence does not prove loader success or runtime invocation.','- Every unwind/entry/export seed is represented in function coverage. Emitted pseudocode VA comments are matched to ledger rows and line anchors normalized.','', '## Build and declaration checks','','The portable `mpasdesc_model` C11 shared-library target compiled with GCC 12.2.0, Debug/PIC and `-Wall -Wextra -Werror -Wpedantic`. See `compatibility-rebuild.log`. CMake deliberately excludes unverified pseudocode. The recovered enum/table header syntax and width checks passed (`header-validation.log`). These are Linux model/declaration checks, not Windows DLL builds.','', '## Controlled instruction-emulation comparisons','',f"**{b['result'].upper()}**: {b['resolver_cases']:,} resolver cases plus six simple-export cases using Unicorn {b['unicorn_version']}.",'','- Compare original resolver at MpAsDesc RVA `0x1768` with compiled independent C decision logic. Verify HRESULT-like result, output/no-write behavior, callback ID sequence, original handle argument and buffer capacity 2.','- Test every category 1..7 with values 0..1001 and 0x7fffffff/0x80000000/0xffffffff; negative/zero/8/maximum categories, null output, resource absent/present and nonempty pt-BR string availability.','- The model’s seven 12-byte table records match original bytes at RVA `0x11f0`.','- Original 64-bit module-handle accessors return controlled zero/nonzero globals. Original aliased registration entries in MpOAV and MsMpCom return `0x80070032`.','- Full test receipt, boundary samples, stub assumptions and outcome digest: `behavior-validation.json`. No real Windows process, registry changes, scans or network requests occurred.','', '## Known discrepancies and repaired analysis infrastructure','','1. Angr’s first automatic MpAsDesc resolver output misplaced a fallback assignment in the out-of-range branch. Disassembly and emulation support the manual model; the automatic rendering remains labeled unverified rather than silently represented as equivalent C.','2. The initial four large-module runs returned empty call-site collections with default size-dependent angr caches and inflated candidate counts. Those outputs were superseded by reruns with function/CFG node/edge caches disabled. `cache-issue.json` preserves initial identities/settings/counts. This workaround restores call-site evidence; the precise upstream cache defect has not been fully diagnosed.','3. Angr initially created a temporary runtime database adjacent to MpSvc in bin/. Original bytes were untouched. The sidecar was removed from the input tree after completion and RTDB_BASE is now forced under ignored analysis/tools/runtime before importing angr.','4. Pseudocode line anchors had an initial one-line offset; validation now derives them from actual VA comment locations.','5. Rebuilding the same Debug model in a different directory changed the ELF bytes (debug/build metadata); behavior tests were rerun against the final src/.../build location rather than asserting binary identity.','', '## Coverage is bounded, not semantic equivalence','']+summary_table+['',f"Total: {emitted:,}/{total:,} candidate starts emitted automated pseudocode; {unwind_emitted:,}/{unwind:,} original unwind starts emitted; {exports_emitted}/{exports} export names have corresponding output (aliases can share one function). Omissions: {dict(omissions)}.",'','All successful automatic outputs can still have incorrect types, control-flow structure or function boundaries. Exact timeout/error/deferred/non-recovered VA rows are retained. Resource-only images have no executable code target. No entire Defender module has been certified equivalent to the original.','', '## Validation not performed','','- Windows loader/MUI behavior, real COM activation, RPC client/server interoperability, service installation/lifecycle, driver interaction, real-time monitoring and UI actions.','- Live downloads, telemetry/authentication or threat scanning; engine, driver, signature data and service host inputs are absent.','- Independent Windows LoadTypeLib/Wine validation of the bounded MSFT decoder.','- All-path symbolic verification, malformed-input fuzzing of reconstructed parsers, complete synchronization/error-path verification, full call-graph reachability, publisher trust and packed-code proof.','']
    (REPORT/'validation.md').write_text('\n'.join(validation))
    final=['# Windows 7 Defender binary analysis — consolidated report','', '**Status: comprehensive input accounting and reproducible structural/automated analysis pass; full behavioral reconstruction remains incomplete.**','', '## Delivered','',f'- All **{len(inventory)} input files** accounted for: **{len(pes)} AMD64 PE32+ images** and two text artifacts. Fifteen module directories preserve original filename boundaries; three pt-BR satellites use a `pt-BR__` prefix.', '- Original bin/ bytes verified against both baseline SHA-256 and original Git objects. No original binary was overwritten.', '- Exact PE/section/import/export/resource/debug/relocation/unwind inventories; raw offset-linked strings; compressed GNU disassembly; independent Capstone call/jump sites; CFG calls/xrefs/indirect-jump evidence.', '- Actual REA 6.5.0 execution on every PE: artifact inspection plus managed classification, with full evidence envelopes and independent hash/header cross-checks.', f'- Automated pseudocode for **{emitted:,} of {total:,} candidate function starts** across {len(code)} code-bearing images. These are candidate/inferred functions, not a count of understood source functions. Per-address omissions are explicit.', f'- Metadata-backed COM declarations for **19 methods**, three dispatch interfaces, six coclasses and five enum constants; **{literal} locally traced literal dynamic-API arguments** across the corpus.', '- A manually reviewed, buildable MpAsDesc non-tracing resolver model. It is a portable behavior model, not a replacement Windows Defender DLL.', f'- **{b["resolver_cases"]:,} original-instruction/model comparison cases passed**, plus six simple-export cases. Structural/provenance checks: **{v["check_count"]:,} checks, {len(v["failed"])} failures**.', '', '## Findings with strongest evidence','', '1. **The supplied code is native x64, not managed CIL.** REA’s managed inspector and pefile agree on the absent CLI directory. Ten images contain code; five are resource-only.', '2. **MpClient is the main statically imported internal API surface.** MSASCui, MpCmdRun, MpSvc, MpCommu, MpRTP and MsMpCom import it. MpClient exports configuration, scan, threat, cleanup, handle and utility entry points; prototypes mostly remain unknown.', '3. **There is a dynamic plugin/utility layer.** MpSvc contains direct GetProcAddress literal requests for all eight MpPlugin names. MpClient requests description/communication entry points, and MpOAV requests MpClient scan/config/handle functions. This is static evidence of lookup code, not proof that a runtime load succeeds.', '4. **MpAsDesc’s resolver returns fallbacks successfully.** Valid categories are signed 1..7; value comparison is unsigned; a missing string or out-of-range value selects a fixed fallback and returns zero. Invalid category/null output returns 0x80070057. The original probes LoadStringW with a two-code-unit buffer.', '5. **Registration exports are not installers.** MpOAV and MsMpCom each alias DllRegisterServer/DllUnregisterServer to a constant 0x80070032 return despite having REGISTRY resources.', '6. **COM metadata materially improves interface recovery.** MsMpCom’s MSFT typelib carries factory, client utility and simple-configuration interfaces. Imported href types are kept unresolved, not guessed. The five configuration enum constants are not Windows REG_* values.', '7. **The corpus mixes builds and lacks major runtime components.** Most native code reports 6.1.7601.23403; event/localized resources report 6.1.7600.16385. Engine DLL, service executable, filter driver, signatures and matching PDBs are absent. Version strings and filename references alone do not establish compatibility.', '', '## REA contribution and constraint','', 'REA was inspected, installed and executed, not merely cited. Its provider-free PE artifact/managed inspectors supplied independent identity/classification evidence. REA did not generate native pseudocode: Ghidra/Hopper/IDA were unavailable; official Ghidra/JDK downloads failed at a disallowed release-assets host. Angr, pefile, objdump, Capstone and Unicorn supplied clearly attributed fallbacks. See methodology.md and rea-limitations.md.', '', '## Coverage summary','']+summary_table+['', 'A row’s emitted count is **not** a successful build, behavioral verification or original-source recovery claim. Candidate counts include inferred leaves and potential false positives. `.pdata` can split funclets. Seven unique export bodies have scoped original-instruction review indexed in `manual-review-index.json`; this does not certify automatic pseudocode. Tests cover only stated controlled conditions.', '', '## Remaining work, in priority order','', '1. Supply a supported Ghidra/JDK or IDA installation and matching PDBs, then cross-check high-risk functions and decompiler discrepancies through REA. Prioritize the per-VA timeout/non-recovered/deferred rows, not undirected rescanning.', '2. Recover MpClient/MpSvc NDR/RPC structures and request dispatch; confirm dynamic module-handle provenance; reconstruct plugin callback structures, ownership, locking and state transitions.', '3. Resolve external COM typelib references, recover implementation vtables and compare type metadata with Windows LoadTypeLib or Wine. Finish MUI/WEVT/dialog/menu/accelerator decoding.', '4. Obtain matching missing runtime artifacts and run controlled Windows VM comparisons. Keep tests offline unless network behavior is an explicitly isolated test objective.', '5. Expand buildable compatibility modules only as behavior becomes specified and validated. Do not replace opaque DLLs with fabricated successful stubs.', '', '## Navigation','', '- [Inventory](inventory.md) — all original identities and structural status.', '- [Methodology](methodology.md) — versions, actual commands, configuration and reproducibility.', '- [Module findings](module-analysis.md), [API map](api-map.md), [dependencies](dependencies.md), [formats](data-formats.md).', '- [Progress and unresolved work](progress.md), [validation](validation.md), machine-readable per-function evidence in `modules/`.', '- Recovered code/interfaces/resources: `../../src/`. Custom infrastructure: `../tools/README.md`.', '', 'No entire Windows Defender executable or DLL is claimed fully reconstructed, buildable or behaviorally equivalent. The saved project makes the verified subset and remaining work auditable.', '']
    (REPORT/'final-report.md').write_text('\n'.join(final))
    print('Final report:',emitted,'/',total,'candidate pseudocode;',v['check_count'],'checks;',b['resolver_cases'],'behavior cases')
if __name__=='__main__':main()
